package order

import (
    "context"
    "fmt"
)

type Service struct { tx TxManager; ids IDGenerator; clock Clock }

func (s Service) Create(ctx context.Context, cmd CreateCommand) (Order, error) {
    if cmd.Quantity <= 0 { return Order{}, fmt.Errorf("quantity must be positive") }
    out := Order{ID: s.ids.New(), ProductID: cmd.ProductID, Quantity: cmd.Quantity, CreatedAt: s.clock.Now()}
    err := s.tx.WithTx(ctx, func(stores Stores) error {
        if err := stores.Orders.Save(ctx, out); err != nil { return fmt.Errorf("save order: %w", err) }
        event := Event{Type: "order.created", AggregateID: out.ID}
        if err := stores.Outbox.Append(ctx, event); err != nil { return fmt.Errorf("append outbox: %w", err) }
        return nil
    })
    if err != nil { return Order{}, fmt.Errorf("create order: %w", err) }
    return out, nil
}

