package app

import (
    "context"
    "fmt"
    "github.com/jackc/pgx/v5/pgxpool"
)

func Run(ctx context.Context, cfg Config) error {
    pool, err := pgxpool.New(ctx, cfg.DatabaseURL)
    if err != nil { return fmt.Errorf("create database pool: %w", err) }
    defer pool.Close()
    if err := pool.Ping(ctx); err != nil { return fmt.Errorf("ping database: %w", err) }
    repo := NewRepository(pool)
    service := NewService(repo, cfg.Clock)
    handler := NewHandler(service)
    if err := RunHTTP(ctx, cfg.HTTP, handler); err != nil { return fmt.Errorf("run http: %w", err) }
    return nil
}
